{"__dsh_paper":"ir-container-v1","entries":[{"kind":"SymbolSpec","value":{"symbol_id":"S-P0","scope_ref":"P1","token":"p0","meaning":"供应商声称的零配件次品率标称值","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ALPHA","scope_ref":"P1","token":"alpha","meaning":"情形(1)的显著性水平","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-BETA","scope_ref":"P1","token":"beta","meaning":"情形(2)的第二类错误概率上界","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-N","scope_ref":"P1","token":"n","meaning":"最小抽样样本量","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C","scope_ref":"P1","token":"c","meaning":"拒收临界值","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P1","scope_ref":"P2","token":"p1","meaning":"零配件1的次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P2","scope_ref":"P2","token":"p2","meaning":"零配件2的次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PF","scope_ref":"P2","token":"pf","meaning":"成品次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C1","scope_ref":"P2","token":"c1","meaning":"零配件1购买单价","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C2","scope_ref":"P2","token":"c2","meaning":"零配件2购买单价","unit":"元/件","role":"PARAMETER","shape":