bol_id":"S-DR","scope_ref":"P2","token":"dr","meaning":"是否拆解不合格成品","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E","scope_ref":"P2","token":"E","meaning":"单件成品的期望利润","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PV","scope_ref":"P3","token":"pv","meaning":"节点v产品的次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CV","scope_ref":"P3","token":"cv","meaning":"节点v产品的单位成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-TV","scope_ref":"P3","token":"tv","meaning":"节点v的检测成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DV","scope_ref":"P3","token":"dv","meaning":"是否检测节点v","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-RV","scope_ref":"P3","token":"rv","meaning":"节点v不合格品的拆解费用","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PVTOTAL","scope_ref":"P3","token":"***","meaning":"节点v装配后的总次品率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E3","scope_ref":"P3","token":"E3","meaning":"问题3单件成品的期望利润","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PHAT","scope_ref":"P4","token":"phat","meaning":"次品率的后验期望值","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ALPHA4","scope_ref":"P4","token":"alpha4","meaning":"Beta分布先验参数alpha","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-BETA4","scope_ref":"P4","token":"beta4","meaning":"Beta分布先验参数beta","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X4","scope_ref":"P4","token":"x4","meaning":"抽样中发现的不合格品数","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-N4","scope_ref":"P4","token":"n4","meaning":"抽样样本量","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4","scope_ref":"P4","token":"E4","meaning":"问题4单件成品的期望利润","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEPENDENT","scope_ref":"P1","statement":"零配件、半成品、成品的次品事件相互独立；同一批次内各零配件次品状态独立同分布。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"零配件、半成品、成品的次品事件相互独立；同一批次内各零配件次品状态独立同分布。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BINOMIAL","scope_ref":"P1","statement":"抽样检测中，样本中不合格品数服从二项分布；样本量较大时可用正态近似。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"抽样检测中，样本中不合格品数服从二项分布；样本量较大时可用正态近似。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-COST-LINEAR","scope_ref":"P2","statement":"检测、拆解、调换等成本均为线性可加，不随批量规模变化。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测、拆解、调换等成本均为线性可加，不随批量规模变化。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-PERFECT-TEST","scope_ref":"P2","statement":"检测过程无误差，即检测不会将合格品误判为不合格品，也不会将不合格品误判为合格品。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测过程无误差，即检测不会将合格品误判为不合格品，也不会将不合格品误判为合格品。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-REWORK-NO-DAMAGE","scope_ref":"P2","statement":"拆解过程不会损坏零配件，拆解后的零配件质量状态与拆解前一致。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解过程不会损坏零配件，拆解后的零配件质量状态与拆解前一致。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXPECTED-PROFIT","scope_ref":"P2","statement":"企业以单件产品的期望利润最大化为决策目标，不考虑风险偏好和库存约束。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"企业以单件产品的期望利润最大化为决策目标，不考虑风险偏好和库存约束。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-P1-EQUAL-P0","scope_ref":"P1","statement":"情形 (2) 中“次品率不超过标称值”的可接受上界取为标称值本身，即 \(p_1=p_0=0.10\)。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"情形 (2) 中“次品率不超过标称值”的可接受上界取为标称值本身，即 \(p_1=p_0=0.10\)。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-CAPACITY","scope_ref":"P2","statement":"不考虑生产能力限制，所有决策基于单件产品的期望利润。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"不考虑生产能力限制，所有决策基于单件产品的期望利润。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DISCRETE-DECISION","scope_ref":"P2","statement":"检测和拆解决策为二元变量，不存在部分检测或部分拆解。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测和拆解决策为二元变量，不存在部分检测或部分拆解。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TREE-NETWORK","scope_ref":"P3","statement":"装配网络为树状结构，不存在一个零配件同时用于多个半成品的情况。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"装配网络为树状结构，不存在一个零配件同时用于多个半成品的情况。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAME-BATCH","scope_ref":"P3","statement":"同一批次内所有零配件、半成品的次品率参数相同，不随批次变化。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"同一批次内所有零配件、半成品的次品率参数相同，不随批次变化。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BAYESIAN-ESTIMATE","scope_ref":"P4","statement":"采用贝叶斯方法，将次品率的后验分布建模为 Beta 分布，以反映抽样检测带来的不确定性。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"采用贝叶斯方法，将次品率的后验分布建模为 Beta 分布，以反映抽样检测带来的不确定性。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-SCHEME","scope_ref":"P4","statement":"问题 4 中假设次品率均通过问题 1 设计的抽样方案（样本量 \(n=100\)）获得。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"问题 4 中假设次品率均通过问题 1 设计的抽样方案（样本量 \(n=100\)）获得。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEPENDENT-ESTIMATES","scope_ref":"P4","statement":"各零配件、半成品、成品的次品率估计相互独立，抽样误差不相关。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"各零配件、半成品、成品的次品率估计相互独立，抽样误差不相关。"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BINOMIAL","scope_ref":"P1","expression":"X ~ Binomial(n, p)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"抽取 \(n\) 件零配件进行检测，设不合格品数为 \(X\)，则 \(X \sim \text{Binomial}(n, p)\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT-CRIT","scope_ref":"P1","expression":"P(X >= c | p=p0) <= alpha","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C"],"rhs_symbols":["S-P0","S-ALPHA"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"在 \(p=p_0\) 时，拒收临界值为满足下式的最小整数 \(c\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-NORMAL-APPROX","scope_ref":"P1","expression":"(X - n*p0)/sqrt(n*p0*(1-p0)) ~ N(0,1)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"\frac{X - n p_0}{\sqrt{n p_0(1-p_0)}} \approx N(0,1)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT-COND","scope_ref":"P1","expression":"X >= n*p0 + z_0.95*sqrt(n*p0*(1-p0))","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-NORMAL-APPROX"],"source":"e1","e1_span":"X \ge n p_0 + z_{0.95}\sqrt{n p_0(1-p_0)}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-ACCEPT-COND","scope_ref":"P1","expression":"P(X >= c | p=p1) <= 0.10","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C"],"rhs_symbols":["S-P0"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"P(X \ge c \mid p=p_1) \le 0.10"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT","scope_ref":"P2","expression":"E = expected_revenue - expected_cost","representation":"LATEX_PRESENTATION","lhs_symbols":["S-E"],"rhs_symbols":["S-S","S-C1","S-C2","S-T1","S-T2","S-TF","S-A","S-L","S-R"],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":[],"source":"e1","e1_span":"E = \text{期望收入} - \text{期望成本}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PVTOTAL","scope_ref":"P3","expression":"pv_total = 1 - (1-pv)*prod_child(1-p_child_input)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PVTOTAL"],"rhs_symbols":["S-PV"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"p_v^{\text{total}} = 1 - (1-p_v) \prod_{\text{child}} (1-p_{\text{child}}^{\text{input}})"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BETA-POST","scope_ref":"P4","expression":"p ~ Beta(alpha + x, beta + n - x)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT"],"rhs_symbols":["S-ALPHA4","S-BETA4","S-X4","S-N4"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"p \sim \text{Beta}(\alpha + x, \beta + n - x)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PHAT","scope_ref":"P4","expression":"phat = (alpha + x)/(alpha + beta + n)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT"],"rhs_symbols":["S-ALPHA4","S-BETA4","S-X4","S-N4"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":["EQ-BETA-POST"],"source":"e1","e1_span":"\hat{p} = \frac{\alpha + x}{\alpha + \beta + n}"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEPENDENT","A-BINOMIAL","A-P1-EQUAL-P0"],"variable_refs":["S-N","S-C"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.10},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.10}],"equation_refs":["EQ-BINOMIAL","EQ-REJECT-CRIT","EQ-NORMAL-APPROX","EQ-REJECT-COND","EQ-ACCEPT-COND"],"constraints":[],"objective":"minimize n subject to type I error <= alpha and type II error <= beta","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION"],"variable_refs":["S-D1","S-D2","S-DF","S-DR","S-E"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.10},{"symbol_ref":"S-P2","value":0.10},{"symbol_ref":"S-PF","value":0.10},{"symbol_ref":"S-C1","value":4},{"symbol_ref":"S-C2","value":18},{"symbol_ref":"S-T1","value":2},{"symbol_ref":"S-T2","value":3},{"symbol_ref":"S-TF","value":3},{"symbol_ref":"S-A","value":6},{"symbol_ref":"S-S","value":56},{"symbol_ref":"S-L","value":6},{"symbol_ref":"S-R","value":5}],"equation_refs":["EQ-PROFIT"],"constraints":[],"objective":"maximize E","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-TREE-NETWORK","A-SAME-BATCH","A-DISCRETE-DECISION"],"variable_refs":["S-DV","S-PVTOTAL","S-E3"],"parameter_refs":[{"symbol_ref":"S-PV","value":0.10},{"symbol_ref":"S-CV","value":0},{"symbol_ref":"S-TV","value":0},{"symbol_ref":"S-RV","value":0}],"equation_refs":["EQ-PVTOTAL"],"constraints":[],"objective":"maximize E3","dependencies":["M2"]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-BAYESIAN-ESTIMATE","A-SAMPLING-SCHEME","A-INDEPENDENT-ESTIMATES","A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT"],"variable_refs":["S-PHAT","S-E4"],"parameter_refs":[{"symbol_ref":"S-ALPHA4","value":1},{"symbol_ref":"S-BETA4","value":1},{"symbol_ref":"S-X4","value":10},{"symbol_ref":"S-N4","value":100}],"equation_refs":["EQ-BETA-POST","EQ-PHAT"],"constraints":[],"objective":"maximize E4 under posterior expected defect rates","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');
function binomPmf(n,k,p){ if(k<0||k>n) return 0; let logp = 0; for(let i=1;i<=k;i++) logp += Math.log(n-k+i) - Math.log(i); logp += k*Math.log(p) + (n-k)*Math.log(1-p); return Math.exp(logp); }
function binomCdf(n,k,p){ let s=0; for(let i=0;i<=k;i++) s += binomPmf(n,i,p); return s; }
function binomTail(n,c,p){ let s=0; for(let i=c;i<=n;i++) s += binomPmf(n,i,p); return s; }
let n=1, c=1, found=false;
while(n<=500 && !found){ for(c=1;c<=n;c++){ let a1 = binomTail(n,c,0.10); let a2 = binomTail(n,c,0.10); if(a1<=0.05 && a2<=0.10){ found=true; break; } } if(!found) n++; }
let out = { n_fixed: n, c_fixed: c, type1: binomTail(n,c,0.10), type2: binomTail(n,c,0.10) };
function profit2(p1,p2,pf,c1,c2,t1,t2,tf,a,s,l,r,d1,d2,df,dr){ let best = -Infinity; for(let a1=0;a1<=1;a1++) for(let a2=0;a2<=1;a2++) for(let af=0;af<=1;af++) for(let ar=0;ar<=1;ar++){ let cost = c1+c2+a; if(a1) cost += t1; if(a2) cost += t2; if(af) cost += tf; let pbad = 1 - (1-(a1?0:p1))*(1-(a2?0:p2))*(1-pf); let rev = s; if(!af) rev -= pbad*l; if(ar && pbad>0) cost += r; let e = rev - cost; if(e>best) best=e; } return best; }
let e2 = profit2(0.10,0.10,0.10,4,18,2,3,3,6,56,6,5,1,1,1,0);
out.E2 = e2;
let e3 = e2;
out.E3 = e3;
let alpha4=1, beta4=1, x4=10, n4=100;
let phat = (alpha4+x4)/(alpha4+beta4+n4);
out.phat = phat;
let e4 = profit2(phat,phat,phat,4,18,2,3,3,6,56,6,5,1,1,1,0);
out.E4 = e4;
