tion_id":"EQ-BINOMIAL","scope_ref":"P1","expression":"X ~ Binomial(n, p)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"抽取 \(n\) 件零配件进行检测，设不合格品数为 \(X\)，则 \(X \sim \text{Binomial}(n, p)\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT-CRIT","scope_ref":"P1","expression":"P(X >= c | p=p0) <= alpha","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C"],"rhs_symbols":["S-P0","S-ALPHA"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"在 \(p=p_0\) 时，拒收临界值为满足下式的最小整数 \(c\)："}},{"kind":"EquationSpec","value":{"equation_id":"EQ-NORMAL-APPROX","scope_ref":"P1","expression":"(X - n*p0)/sqrt(n*p0*(1-p0)) ~ N(0,1)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"\frac{X - n p_0}{\sqrt{n p_0(1-p_0)}} \approx N(0,1)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT-COND","scope_ref":"P1","expression":"X >= n*p0 + z_95*sqrt(n*p0*(1-p0))","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-P0","S-Z95"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-NORMAL-APPROX"],"source":"e1","e1_span":"X \ge n p_0 + z_{0.95}\sqrt{n p_0(1-p_0)}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-ACCEPT-COND","scope_ref":"P1","expression":"P(X >= c | p=p1) <= 0.10","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C"],"rhs_symbols":["S-P1"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","e1_span":"P(X \ge c \mid p=p_1) \le 0.10"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT","scope_ref":"P2","expression":"E = 期望收入 - 期望成本","representation":"LATEX_PRESENTATION","lhs_symbols":["S-E2"],"rhs_symbols":[],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":[],"source":"e1","e1_span":"E = \text{期望收入} - \text{期望成本}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PVTOTAL","scope_ref":"P3","expression":"p_v_total = 1 - (1-p_v) * prod_child(1-p_child_input)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PVTOTAL_3"],"rhs_symbols":["S-PV_3"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"p_v^{\text{total}} = 1 - (1-p_v) \prod_{\text{child}} (1-p_{\text{child}}^{\text{input}})"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BETA-POST","scope_ref":"P4","expression":"p ~ Beta(alpha + x, beta + n - x)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT4"],"rhs_symbols":["S-ALPHA4","S-BETA4","S-N4","S-X4"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"p \sim \text{Beta}(\alpha + x, \beta + n - x)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PHAT","scope_ref":"P4","expression":"p_hat = (alpha + x)/(alpha + beta + n)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT4"],"rhs_symbols":["S-ALPHA4","S-BETA4","S-N4","S-X4"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":["EQ-BETA-POST"],"source":"e1","e1_span":"\hat{p} = \frac{\alpha + x}{\alpha + \beta + n}"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEPENDENT","A-BINOMIAL","A-P1-EQUAL-P0"],"variable_refs":["S-N","S-C"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.1},{"symbol_ref":"S-Z95","value":1.645},{"symbol_ref":"S-P1","value":0.1}],"equation_refs":["EQ-BINOMIAL","EQ-REJECT-CRIT","EQ-NORMAL-APPROX","EQ-REJECT-COND","EQ-ACCEPT-COND"],"constraints":[],"objective":"最小化样本量n，同时满足两类信度约束","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION"],"variable_refs":["S-E2","S-D1_2","S-D2_2","S-DF_2","S-DR_2"],"parameter_refs":[{"symbol_ref":"S-P1_2","value":0.1},{"symbol_ref":"S-P2_2","value":0.1},{"symbol_ref":"S-PF_2","value":0.1},{"symbol_ref":"S-C1_2","value":4},{"symbol_ref":"S-C2_2","value":18},{"symbol_ref":"S-T1_2","value":2},{"symbol_ref":"S-T2_2","value":3},{"symbol_ref":"S-TF_2","value":3},{"symbol_ref":"S-A_2","value":6},{"symbol_ref":"S-S_2","value":56},{"symbol_ref":"S-L_2","value":6},{"symbol_ref":"S-R_2","value":5}],"equation_refs":["EQ-PROFIT"],"constraints":[],"objective":"最大化单件成品期望利润E","dependencies":["M1"]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION","A-TREE-NETWORK","A-SAME-BATCH"],"variable_refs":["S-E3","S-DV_3","S-PVTOTAL_3"],"parameter_refs":[{"symbol_ref":"S-PV_3","value":0.1},{"symbol_ref":"S-CV_3","value":0},{"symbol_ref":"S-TV_3","value":0},{"symbol_ref":"S-RV_3","value":0}],"equation_refs":["EQ-PVTOTAL"],"constraints":[],"objective":"最大化单件成品期望利润E","dependencies":["M2"]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION","A-TREE-NETWORK","A-SAME-BATCH","A-BAYESIAN-ESTIMATE","A-SAMPLING-SCHEME","A-INDEPENDENT-ESTIMATES"],"variable_refs":["S-E4","S-PHAT4"],"parameter_refs":[{"symbol_ref":"S-N4","value":100},{"symbol_ref":"S-X4","value":10},{"symbol_ref":"S-ALPHA4","value":1},{"symbol_ref":"S-BETA4","value":1}],"equation_refs":["EQ-BETA-POST","EQ-PHAT"],"constraints":[],"objective":"最大化次品率估计误差下的单件成品期望利润E","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');
function binomPmf(n,k,p){ if(k<0||k>n) return 0; let logP = 0; for(let i=1;i<=k;i++) logP += Math.log(n-k+i)-Math.log(i); logP += k*Math.log(p)+(n-k)*Math.log(1-p); return Math.exp(logP); }
function binomCdf(n,k,p){ let s=0; for(let i=0;i<=k;i++) s+=binomPmf(n,i,p); return Math.min(1,s); }
function binomTail(n,c,p){ let s=0; for(let i=c;i<=n;i++) s+=binomPmf(n,i,p); return Math.min(1,s); }
let n=0,c=0;
for(let nn=1;nn<=500;nn++){ let found=false; for(let cc=0;cc<=nn;cc++){ let a=binomTail(nn,cc,0.1); let b=binomTail(nn,cc,0.1); if(a<=0.05 && b<=0.10){ n=nn; c=cc; found=true; break; } } if(found) break; }
function profit2(p1,p2,pf,c1,c2,t1,t2,a,tf,s,l,r,d1,d2,df,dr){ let pc1=d1?0:p1, pc2=d2?0:p2; let cost1=d1?c1+t1:c1; let cost2=d2?c2+t2:c2; let pBad=1-(1-pc1)*(1-pc2)*(1-pf); let E=s; if(df){ E-=tf; } else { E-=pBad*l; } E-=cost1+cost2+a; if(dr && df){ E-=pBad*r; } return E; }
let best2=null,bestE2=-Infinity;
for(let d1=0;d1<=1;d1++)for(let d2=0;d2<=1;d2++)for(let df=0;df<=1;df++)for(let dr=0;dr<=1;dr++){ let e=profit2(0.1,0.1,0.1,4,18,2,3,6,3,56,6,5,d1,d2,df,dr); if(e>bestE2){bestE2=e;best2=[d1,d2,df,dr];} }
function profit3(){ let p=0.1; let cost=0; for(let i=0;i<8;i++) cost+=4+2; cost+=6; let pBad=1-Math.pow(1-p,3); let E=56-3-pBad*6-cost; return E; }
let bestE3=profit3();
let n4=100,x4=10,a4=1,b4=1;
let pHat=(a4+x4)/(a4+b4+n4);
let bestE4=profit2(pHat,pHat,pHat,4,18,2,3,6,3,56,6,5,best2[0],best2[1],best2[2],best2[3]);
let out={n_fixed:n,c_fixed:c,alpha_actual:binomTail(n,c,0.1),beta_actual:binomTail(n,c,0.1),E2:bestE2,d1:best2[0],d2:best2[1],df:best2[2],dr:best2[3],E3:bestE3,E4:bestE4,p_hat:pHat};
