iable_refs":["S-E2","S-D1_2","S-D2_2","S-DF_2","S-DR_2"],"parameter_refs":[{"symbol_ref":"S-P1_2","value":0.1},{"symbol_ref":"S-P2_2","value":0.1},{"symbol_ref":"S-PF_2","value":0.1},{"symbol_ref":"S-C1_2","value":4},{"symbol_ref":"S-C2_2","value":18},{"symbol_ref":"S-T1_2","value":2},{"symbol_ref":"S-T2_2","value":3},{"symbol_ref":"S-TF_2","value":3},{"symbol_ref":"S-A_2","value":6},{"symbol_ref":"S-S_2","value":56},{"symbol_ref":"S-L_2","value":6},{"symbol_ref":"S-R_2","value":5}],"equation_refs":["EQ-PROFIT"],"constraints":[],"objective":"maximize E","dependencies":["M1"]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION","A-TREE-NETWORK","A-SAME-BATCH"],"variable_refs":["S-E3","S-PVTOTAL_3","S-DV_3"],"parameter_refs":[{"symbol_ref":"S-PV_3","value":0.1},{"symbol_ref":"S-CV_3","value":0},{"symbol_ref":"S-TV_3","value":0},{"symbol_ref":"S-RV_3","value":0}],"equation_refs":["EQ-PVTOTAL"],"constraints":[],"objective":"maximize E3","dependencies":["M2"]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-BAYESIAN-ESTIMATE","A-SAMPLING-SCHEME","A-INDEPENDENT-ESTIMATES","A-INDEPENDENT","A-COST-LINEAR","A-PERFECT-TEST","A-REWORK-NO-DAMAGE","A-EXPECTED-PROFIT","A-NO-CAPACITY","A-DISCRETE-DECISION"],"variable_refs":["S-E4","S-PHAT4"],"parameter_refs":[{"symbol_ref":"S-X4","value":10},{"symbol_ref":"S-N4","value":100},{"symbol_ref":"S-ALPHA4","value":1},{"symbol_ref":"S-BETA4","value":1}],"equation_refs":["EQ-BETA-POST","EQ-PHAT"],"constraints":[],"objective":"maximize E4 under posterior uncertainty","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');
function binomPmf(n,k,p){ if(k<0||k>n) return 0; let logP = 0; for(let i=1;i<=k;i++) logP += Math.log(n-k+i) - Math.log(i); logP += k*Math.log(p) + (n-k)*Math.log(1-p); return Math.exp(logP); }
function binomCdf(n,k,p){ let s=0; for(let i=0;i<=k;i++) s += binomPmf(n,i,p); return s; }
function binomTail(n,k,p){ let s=0; for(let i=k;i<=n;i++) s += binomPmf(n,i,p); return s; }
