function profitQ2(d1,d2,df,dr){
  const p1=0.1,p2=0.1,pf=0.1,c1=4,c2=18,t1=2,t2=3,a=6,tf=3,s=56,l=6,r=5;
  let E=0;
  for(let iter=0;iter<100;iter++){
    let cost=0, rev=0;
    let p1in = d1?0:p1, p2in = d2?0:p2;
    cost += c1 + (d1?t1:0) + c2 + (d2?t2:0) + a;
    let pBad = 1 - (1-p1in)*(1-p2in)*(1-pf);
    if(df){ cost += tf; rev += s*(1-pBad); }
    else { rev += s*(1-pBad) - l*pBad; }
