// Q3: simplified tree enumeration (8 parts, 2 subassemblies, 1 final)
function profitQ3(decisions){
  const p=0.1, cPart=2, tPart=1, aSub=3, tSub=2, aFinal=5, tFinal=3, s=100, l=10, r=5;
