function binomPmf(n,k,p){ if(k<0||k>n) return 0; let log=0; for(let i=1;i<=k;i++) log += Math.log(n-k+i)-Math.log(i); log += k*Math.log(p)+(n-k)*Math.log(1-p); return Math.exp(log); }
function binomCdf(n,k,p){ let s=0; for(let i=0;i<=k;i++) s+=binomPmf(n,i,p); return Math.min(1,s); }
function binomSurv(n,k,p){ return 1-binomCdf(n,k-1,p); }
